    }
    return normalizedPath;
  }

  public createEventSink(
    runId: string,
    baseName: string,
    directory: 'devserver' | 'events' | `checkpoints/${string}`,
    options?: Partial<
      Omit<EventSinkOptions, 'repoRoot' | 'relativeDirectory' | 'baseName' | 'capTracker'>
    >,
  ): NdjsonEventSink {
    const runPaths = this.getRunPaths(runId);
    const relativeDirectory =
      directory === 'devserver'
        ? runPaths.devServerRoot
        : directory === 'events'
          ? runPaths.eventRoot
        : path.posix.join(runPaths.runRoot, directory);

    return new NdjsonEventSink({
      repoRoot: this.repoRoot,
      relativeDirectory,
      baseName,
      capTracker: this.capTracker,
      ...(options?.policy ? { policy: options.policy } : {}),
    });
  }

  private async writeJson(relativePath: string, value: object): Promise<void> {
    // Serialize once so the reserved byte count and persisted bytes are identical.
    await this.writeText(relativePath, `${JSON.stringify(value, null, 2)}\n`);
  }

  private async writeText(relativePath: string, contents: string | Uint8Array): Promise<void> {
    const normalizedPath = assertRepositoryRelativePath(relativePath);
    const snapshot = typeof contents === 'string' ? contents : new Uint8Array(contents);
    const bytes = typeof snapshot === 'string' ? Buffer.byteLength(snapshot) : snapshot.byteLength;
    const reservation = this.capTracker.reserve(bytes, normalizedPath);
    // Also serialize replacements: atomic writer temp names are time based, and two
    // simultaneous writes to one destination must not share a temporary file.
    const operation = this.writeQueue.then(async () => {
      try { await writeAtomicFile(this.repoRoot, normalizedPath, snapshot); }
      finally {
        // A failed atomic writer may have created a partial temporary file or renamed
        // before failing its stat. Conservatively charge the attempt, including overwrites.
        reservation.commit();
      }
    });
    this.writeQueue = operation.then(() => undefined, () => undefined);
    await operation;
  }
}

function sanitizeSegment(value: string): string {
  const sanitized = value
    .trim()
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '');

  if (sanitized.length === 0) {
    throw createProbefnError({
      code: 'E_STORAGE_WRITE_FAILED',
      message: 'Checkpoint names must contain at least one safe character.',
      retryable: false,
      details: {
        value,
      },
    });
  }

  assertArtifactIdentifier(sanitized, 'Checkpoint name');
  return sanitized;
}

function assertRunId(runId: string): void {
  assertArtifactIdentifier(runId, 'Run id');
}
import { createProbefnError } from '@probefn/contracts/errors';

export interface StorageCaps {
  maxArtifactBytes: number;
  maxEventsPerSink: number;
}

export interface EventCapPolicy {
  maxEventsPerSink: number;
  strategy: 'rollover' | 'error';
}

export const DEFAULT_STORAGE_CAPS: StorageCaps = {
  maxArtifactBytes: 2 * 1024 * 1024 * 1024,
  maxEventsPerSink: 50_000,
};

export class ArtifactCapTracker {
  // Cumulative attempted payload budget, not exact disk usage (overwrites are charged again).
  private totalBytesWritten = 0;
  private reservedBytes = 0;

  public constructor(private readonly maxBytes: number = DEFAULT_STORAGE_CAPS.maxArtifactBytes) {
    if (!Number.isSafeInteger(maxBytes) || maxBytes < 0) throw new TypeError('Artifact byte cap must be a non-negative safe integer.');
  }

  public getTotalBytesWritten(): number {
    return this.totalBytesWritten;
  }

  public assertCanWrite(nextBytes: number, targetPath: string): void {
    if (!Number.isSafeInteger(nextBytes) || nextBytes < 0) {
      throw createProbefnError({
        code: 'E_STORAGE_WRITE_FAILED',
        message: `Refusing to write a invalid byte count for ${targetPath}.`,
        retryable: false,
        details: {
          targetPath,
          nextBytes,
        },
      });
    }

    if (this.totalBytesWritten + this.reservedBytes + nextBytes > this.maxBytes) {
      throw createProbefnError({
        code: 'E_STORAGE_CAP_EXCEEDED',
        message: `Artifact cap exceeded before ${targetPath} could be committed.`,
        retryable: false,
        details: {
          targetPath,
          maxArtifactBytes: this.maxBytes,
          attemptedTotalBytes: this.totalBytesWritten + this.reservedBytes + nextBytes,
        },
      });
    }
  }

  /** Reserve synchronously before any asynchronous write. Settle exactly once. */
  public reserve(bytes: number, targetPath: string): { commit(): void; release(): void } {
    this.assertCanWrite(bytes, targetPath);
    this.reservedBytes += bytes;
    let settled = false;
    return {
      commit: () => {
        if (settled) return;
        settled = true;
        this.reservedBytes -= bytes;
        this.totalBytesWritten += bytes;
      },
      release: () => {
        if (settled) return;
        settled = true;
        this.reservedBytes -= bytes;
      },
    };
  }

  /** Legacy accounting; asynchronous writers must use reserve() instead. */
  public recordWrite(bytesWritten: number): void {
    this.totalBytesWritten += bytesWritten;
  }
}
