  // Integration helpers
  use(integration: any, options?: any) {
      // Logic to attach integration
  }

  // Transaction helper
  startTransaction(name: string) {
      return this.tracer.startTransaction(name);
  }
}

export function watchFn(config: WatchFnConfig): WatchFn {
