      .map(([path, operations]) => [
        path,
        Object.fromEntries(
          [...operations.entries()].sort(([left], [right]) => compareMethods(left, right))
        )
      ])
  );

  return {
    openapi: "3.1.0",
    info: {
      title: input.title,
      version: input.version
