    for (const dir of WRAPPER_SOURCE_DIRS) {
      const fullPath = resolve(MONOREPO_ROOT, dir);
      let output = "";
      try {
        output = execSync(
          `grep -rn --include='*.ts' "DocId" "${fullPath}" || true`,
