        ).trim();
      } catch {
        output = "";
      }

      const matches = output
        .split("\n")
        .filter((l) => l.length > 0)
        .filter((l) => l.includes("@searchfn/core") && l.includes("DocId"));

      expect(
        matches,
        `Legacy DocId import from @searchfn/core found in ${dir}: ${matches.join(", ")}`,
      ).toEqual([]);
    }
  });
});
