    .replace(KEY_VALUE_SECRET, (_match, key) => `${key}=[REDACTED]`)
    .replace(URL_CREDENTIALS, "$1[REDACTED]@")
    .replace(POSTGRES_CREDENTIALS, "$1[REDACTED]@");
